#include <iostream>
#include <unordered_map>
using namespace std;

int check(int n) {
    if (n == 2) {
        return 0;
    }
    if (n % 2 == 0) {
        return 1;
    }
    return 0;
}

int ans(int n, int m) {
    unordered_map<int, int> pattern_map = {{0, 0}, {1, 1}, {2, 2}, {3, 3}, {4, 2}, {5, 1}};
    if (m == 1) {
        return pattern_map[n % 6];
    } else if (m == 2) {
        if (n == 3) {
            return 2;
        } else if (n == 2) {
            return 4;
        } else if (n == 7) {
            return 2;
        }
    }
    return (n * m) % 2;
}

int main() {
    int n, m;
    cin >> n >> m;
    int n1 = n, m1 = m;
    if (n < m) {
        int temp = n;
        n = m;
        m = temp;
    }
    cout << n * m - ans(n, m) << endl;
    return 0;
}
